1: import {
2:   renderWeatherCard,
3:   renderWeatherGrid,
4:   renderWeatherGridToElement,
5:   injectStyles,
6:   resolveCondition,
7:   unitOf,
8: } from '../src/weather-card.js';
9: 
10: let failures = 0;
11: function check(cond, name) {
12:   if (!cond) { failures++; console.error('FAIL ' + name); }
13:   else console.log('ok   ' + name);
14: }
15: 
16: const tokyo = {
17:   city: 'Tokyo',
18:   temp: 22,
19:   condition: 'partly-cloudy',
20:   description: 'Mostly sunny',
21:   humidity: 65,
22:   windKmh: 12,
23:   windDirection: 'NW',
24:   high: 25,
25:   low: 17,
26:   time: '14:18',
27:   hourly: [{ time: '15:00', temp: 21, condition: 'rain' }],
28: };
29: 
30: const html = renderWeatherCard(tokyo);
31: check(html.includes('Tokyo'), 'card renders city');
32: check(html.includes('22'), 'card renders temperature');
33: check(html.includes('°C'), 'card renders unit');
34: check(html.includes('🌤️'), 'card picks correct icon');
35: check(html.includes('Mostly sunny'), 'card renders description');
36: check(html.includes('65%'), 'card renders humidity');
37: check(html.includes('12 km/h NW'), 'card renders wind');
38: check(html.includes('25° / 17°'), 'card renders high/low');
39: check(renderWeatherGrid([tokyo]).includes('wc-grid'), 'grid renders');
40: check(renderWeatherGrid([tokyo]).includes('role="list"'), 'grid has role=list');
41: check(renderWeatherGrid([tokyo]).includes('15:00'), 'hourly forecast renders');
42: 
43: // condition resolution
44: check(resolveCondition({ condition: 'clear' }).code === 'clear', 'known code');
45: check(resolveCondition({ condition: 'heavy-rain' }).code === 'heavy-rain', 'known code 2');
46: check(resolveCondition({ condition: 'light rain' }).code === 'rain', 'keyword: light rain');
47: check(resolveCondition({ condition: 'thunderstorm' }).code === 'thunderstorm', 'keyword: thunderstorm');
48: check(resolveCondition({ condition: 'Foggy' }).code === 'fog', 'keyword: foggy');
49: check(resolveCondition({ condition: 'sunny' }).code === 'clear', 'keyword: sunny');
50: check(resolveCondition({ condition: '???' }).code === 'cloudy', 'unknown falls back');
51: check(resolveCondition({ condition: 'cloudy' }).code === 'cloudy', 'icon name accepted');
52: 
53: // units
54: check(unitOf({ temp: 1, unit: 'F' }) === '°F', 'Fahrenheit unit');
55: check(unitOf({ temp: 1, unit: '°F' }) === '°F', '°F unit');
56: check(unitOf({ temp: 1 }) === '°C', 'default Celsius');
57: 
58: // single object accepted for grid
59: check(renderWeatherGrid(tokyo).includes('Tokyo'), 'grid accepts single object');
60: 
61: // browser-only APIs are safe in Node
62: injectStyles();
63: check(true, 'injectStyles safe in Node (no throw)');
64: renderWeatherGridToElement(null, [tokyo]);
65: check(true, 'gridToElement safe with null container in Node (no throw)');
66: 
67: // escaping
68: const xss = { city: '<script>alert(1)</script>', temp: 1 };
69: const out = renderWeatherCard(xss);
70: check(out.includes('&lt;script&gt;'), 'HTML is escaped');
71: check(!out.includes('<script>alert(1)</script>'), 'no raw XSS payload');
72: 
73: if (failures > 0) {
74:   console.error(`\n${failures} failure(s)`);
75:   process.exit(1);
76: }
77: console.log('\nall tests passed');
78: 
